Hlp.UpdatePlayerPanel = function(panel) {
	var profile = GameApp.gm_ctx().profile;
	var company = profile.selectedCompany();
	iriysoft_text_TextRes.SetText(panel,"rank",iriysoft_text_LocId.kRank);
	iriysoft_text_TextRes.SetText(panel,"next",iriysoft_text_LocId.kNext);
	iriysoft_text_TextRes.SetText(panel,"new_free",iriysoft_text_LocId.kFree);
	iriysoft_helper_Fwh.GotoAndStop(panel,"mcPanel",company.info().number() + 1);
	iriysoft_helper_Fwh.SetText(panel,"txtRankNum",Std.string(company.getRank()));
	iriysoft_helper_Fwh.SetText(panel,"txtEdictsNum",Std.string(company.getFreeSkillPoints()));
	if(company.getFreeSkillPoints() > 0) {
		iriysoft_helper_Fwh.SetVisible(panel,"free_edictions_exists",true);
	} else {
		iriysoft_helper_Fwh.SetVisible(panel,"free_edictions_exists",false);
	}
	var curVal = company.getCurXP();
	var maxVal = company.getNextXP();
	if(maxVal == 0) {
		iriysoft_helper_Fwh.SetHtmlText(panel,"txtXP","<FONT COLOR='#FFFF00'> MAX RANK </FONT>");
	} else {
		iriysoft_helper_Fwh.SetHtmlText(panel,"txtXP","<FONT COLOR='#FFFF00'>" + curVal + "</FONT><FONT COLOR='#DBDB02'> / " + maxVal + "</FONT>");
	}
	var progress_bar = iriysoft_helper_Fwh.GetByPathA(panel,["mcXPIndicator","xp_bar_"]);
	progress_bar.stop();
	progress_bar.gotoFrame(Math.round(curVal * progress_bar.get_totalFrames() / maxVal + 1));
};
Hlp.getFormattedTimeBySeconds = function(time,use_hours,use_mins,use_secs_,use_millisecs) {
	var result = "";
	var seconds = Math.floor(time);
	var milliseconds = Math.floor(1000 * (time - seconds));
	var minutes = Math.floor(seconds / 60);
	seconds -= minutes * 60;
	var hours = Math.floor(minutes / 60);
	minutes -= hours * 60;
	if(use_hours) {
		result += hours;
	}
	if(use_mins) {
		if(use_hours) {
			result += ":";
			result += minutes < 10 ? "0" : "";
		}
		result += minutes;
	}
	if(use_secs_) {
		if(use_mins) {
			result += ":";
			result += seconds < 10 ? "0" : "";
		}
		result += seconds;
	}
	if(use_millisecs) {
		if(use_secs_) {
			result += ".";
			result += (milliseconds < 100 ? "0" : "") + (milliseconds < 10 ? "0" : "");
		}
		result += milliseconds;
	}
	return result;
};
