	,onWindowButtonOver: function(v) {
		this.over_lifetime_ = this.lifetime();
		this.ref_level.hintLayer().hideHint();
		var unitID = v.userData._additinalButtonID;
		var cmb = this.ref_level.getCombotants().getObject(this.m_curWindow.combotantDescription);
		var keyNode = Cast.ToFKeyNodeContent(this.m_curWindow.nodeContent);
		var hintText = "";
		switch(unitID) {
		case 0:case 1:case 2:case 3:case 4:
			this.createUnitHint(cmb,unitID,this.m_curWindow.level);
			this.showHintAtButton(this.ref_level.unitHintID(),v);
			return;
		case 5:
			if(keyNode == null) {
				return;
			}
			hintText = this.createUpgradeHintText(keyNode.getLevel() + 1);
			break;
		case 6:
			hintText = this.createSupplyHintText(cmb,level_SupplyBuildingType.Village);
			break;
		case 7:
			hintText = this.createSupplyHintText(cmb,level_SupplyBuildingType.Mine);
			break;
		case 8:
			hintText = this.createSupplyHintText(cmb,level_SupplyBuildingType.Obelisk);
			break;
		case 10:
			this.createUltimateSpellHint(v);
			break;
		default:
			return;
		}
		this.ref_level.hintLayer().getHintWindow(this.ref_level.textHintID()).setText(hintText);
		this.showHintAtButton(this.ref_level.textHintID(),v);
	}
