	,findAndMarkPath: function(_from,_to,_weight) {
		if(_weight == null) {
			_weight = 0.0;
		}
		if(_from.pathFindData.weght > _weight) {
			_from.pathFindData.weght = _weight;
			if(_from != _to) {
				var _g = 0;
				var _g1 = _from.pathFindData.roads;
				while(_g < _g1.length) {
					var r = _g1[_g];
					++_g;
					this.findAndMarkPath(this.m_nodes.getObject(r.getOtherNodeDescription(_from.description)),_to,r.pathFindLength + _weight);
				}
			}
		}
	}
	,getMarkWay: function(_to) {
		var roads = [];
		var node = _to;
		var road;
		while(node.pathFindData.weght > 0) {
			road = this.getShortRoad(node);
			if(road == null) {
				break;
			}
			roads.push(road);
			node = this.m_nodes.getObject(road.getOtherNodeDescription(node.description));
		}
		return roads;
	}
	,getShortRoad: function(_node) {
		var toNode;
		var r;
		var minWight = 999999;
		var shortRoad = null;
		var _g = 0;
		var _g1 = _node.pathFindData.roads;
		while(_g < _g1.length) {
			var r = _g1[_g];
			++_g;
			toNode = this.m_nodes.getObject(r.getOtherNodeDescription(_node.description));
			if(minWight > toNode.pathFindData.weght) {
				minWight = toNode.pathFindData.weght;
				shortRoad = r;
			}
		}
		return shortRoad;
	}
