	,createSpellTerror: function(_spell,_combotant) {
		var iter = this.getSquadsIterator();
		var sqd;
		var race = _combotant.getRace();
		var rad = _spell.radius;
		var pos = new base_Position(_spell.position.x,_spell.position.y);
		while(iter.hasNext()) {
			sqd = Cast.ToFSquad(iter.next());
			if(sqd.getRace() != race) {
				if(sqd.checkUnitAtRadius(pos,rad)) {
					sqd.enableTerror();
				}
			}
		}
		this.createSingleAnimEffect("TerrorSpellEffectClass",pos.x,pos.y,3);
		this.createSingleAnimEffect("TerrorFlyingBatEffectClass",pos.x,pos.y,3);
		this.createSingleAnimEffect("TerrorSplashEffectClass",pos.x,pos.y,0);
		this.playSpellSound(_spell);
	}
