	,UpdateBadges: function() {
		if(this.page_ <= 0) {
			this.left_.set_enable(false);
			this.page_ = 0;
		} else {
			this.left_.set_enable(true);
		}
		if(this.page_ >= this.pages_) {
			this.right_.set_enable(false);
			this.page_ = this.pages_ - 1;
		} else {
			this.right_.set_enable(true);
		}
		var _g = 0;
		var _g1 = ui_BadgesScr.kBadgesPerPage;
		while(_g < _g1) {
			var i = _g++;
			iriysoft_helper_Fwh.SetVisibleByName(this.center_,"badge" + (i + 1),false);
		}
		var begin_index = this.page_ * ui_BadgesScr.kBadgesPerPage;
		var _g = begin_index;
		var _g1 = begin_index + ui_BadgesScr.kBadgesPerPage;
		while(_g < _g1) {
			var i = _g++;
			if(i >= progress_Badges.BADGES_IDS.length) {
				break;
			}
			var cont = js_Boot.__cast(this.center_.getChildByName("badge" + (i - begin_index + 1)) , iriysoft_graphic_IIsfViewObjectContainer);
			cont.set_visible(true);
			var badge = this.gm_ctx_.profile.badges().getBadge(progress_Badges.BADGES_IDS[i]);
			this.FillBadge(cont,badge);
		}
	}
	,FillBadge: function(cont,badge) {
		var view = null;
		if(badge.condition().fulfilled()) {
			cont.getChildByName("locked_").set_visible(false);
			view = cont.getChildByName("unlocked_");
		} else {
			cont.getChildByName("unlocked_").set_visible(false);
			view = cont.getChildByName("locked_");
		}
		view.set_visible(true);
		iriysoft_helper_Fwh.GotoAndStop(view,"icon",badge.iconNum());
		iriysoft_helper_Fwh.SetHtmlText(view,"txtName",badge.name());
		iriysoft_helper_Fwh.SetText(view,"txtDesc",badge.description());
		var metricCondition = js_Boot.__cast(badge.condition().condition() , achievements_MetricCondition);
		iriysoft_helper_Fwh.SetText(view,"txtProgress",metricCondition.metric().value() + " / " + metricCondition.constant());
		var bar = iriysoft_helper_Fwh.GetA(view,"bar");
		var barFrame = 1 + (bar.get_totalFrames() - 1) * metricCondition.metric().value() / metricCondition.constant() | 0;
		bar.gotoFrame(barFrame);
		bar.stop();
	}
