			icon_c.touchGroup = true;
			var icon = new ui_IconUi(icon_c);
			this.spell_icons_.push(icon);
			var icSet = Hlp.FromScreensA("SpellIconSetClass");
			icSet.gotoFrame(spellInfo.id + 1);
