	,UpdateEdict: function(edict_ui,_edictCount) {
		var icon = edict_ui.edict_c;
		var edict = edict_ui.edict;
		iriysoft_helper_Fwh.SetTextByPath(icon,["mcStripe0","mcCaption"],iriysoft_text_TextRes.Get(edict.name));
		var hint = null;
		var hintPrefix = "<FONT COLOR='#FFFFFF'>";
		var enable = false;
		var canBuy = _edictCount >= edict.issuesToUnlock;
		var nextEnable = false;
		var present = false;
		enable = 0 < edict.curPoints;
		nextEnable = 1 < edict.curPoints;
		present = 0 < edict.getContents().length;
		if(enable) {
			hintPrefix = "<FONT COLOR='#FFFF00'>";
		} else if(canBuy) {
			hintPrefix = "<FONT COLOR='#C6CCD2'>";
		} else {
			hintPrefix = "<FONT COLOR='#C6CCD2'>";
		}
		if(present) {
			hint = iriysoft_text_TextRes.Format(edict.getContents()[0].hint,[edict.getContents()[0].bonusVal]);
		}
		this.createScrollIcon(icon,enable,canBuy,0,present,hint,hintPrefix);
		enable = 1 < edict.curPoints;
		nextEnable = 2 < edict.curPoints;
		present = 1 < edict.getContents().length;
		if(enable) {
			hintPrefix = !nextEnable ? "<FONT COLOR='#FFFF00'>" : "<FONT COLOR='#C6CCD2'>";
		} else if(canBuy) {
			hintPrefix = "<FONT COLOR='#C6CCD2'>";
		} else {
			hintPrefix = "<FONT COLOR='#C6CCD2'>";
		}
		if(present) {
			hint = iriysoft_text_TextRes.Format(edict.getContents()[1].hint,[edict.getContents()[1].bonusVal]);
		}
		this.createScrollIcon(icon,enable,canBuy,1,present,hint,hintPrefix);
		enable = 2 < edict.curPoints;
		nextEnable = 3 < edict.curPoints;
		present = 2 < edict.getContents().length;
		if(enable) {
			hintPrefix = !nextEnable ? "<FONT COLOR='#FFFF00'>" : "<FONT COLOR='#C6CCD2'>";
		} else if(canBuy) {
			hintPrefix = "<FONT COLOR='#C6CCD2'>";
		} else {
			hintPrefix = "<FONT COLOR='#C6CCD2'>";
		}
		if(present) {
			hint = iriysoft_text_TextRes.Format(edict.getContents()[2].hint,[edict.getContents()[2].bonusVal]);
		}
		this.createScrollIcon(icon,enable,canBuy,2,present,hint,hintPrefix);
		var company = this.gm_ctx_.profile.selectedCompany();
		if(company.getFreeSkillPoints() == 0 || edict.curPoints == 3) {
			edict_ui.btn.confirm_manual = true;
		} else {
			edict_ui.btn.confirm_manual = false;
		}
		edict_ui.btn.SetConfirm(false);
		edict_ui.btn.set_enable(canBuy);
		if(!canBuy) {
			iriysoft_helper_Fwh.SetVisible(icon,"locked_",true);
			iriysoft_helper_Fwh.SetTextByPath(icon,["locked_","issue_"],iriysoft_text_TextRes.Format(iriysoft_text_LocId.kIssue,[edict.issuesToUnlock]));
			iriysoft_text_TextRes.SetTextByPath(icon,["locked_","to_unlock"],iriysoft_text_LocId.kToUnlock);
		} else {
			iriysoft_helper_Fwh.SetVisible(icon,"locked_",false);
		}
	}
	,createScrollIcon: function(_icon,_enable,_canBuy,_id,_present,_hint,_prefix) {
		var mv = iriysoft_helper_Fwh.GetC(_icon,"mcScrollIcon" + _id);
		iriysoft_helper_Fwh.GotoAndStop(mv,"back_",_enable ? 1 : _canBuy ? 2 : 3);
		iriysoft_helper_Fwh.SetHtmlText(mv,"txtNum",_prefix + Std.string(_id + 1) + "</FONT>");
		mv.set_visible(_present);
		var stripe = iriysoft_helper_Fwh.GetC(_icon,"mcStripe" + _id);
		if(_id != 0) {
			iriysoft_helper_Fwh.SetHtmlText(stripe,"mcCaption",_prefix + _hint + "</FONT>");
		}
		if(_enable) {
			iriysoft_helper_Fwh.GotoAndStop(stripe,"back_",1);
		} else {
			iriysoft_helper_Fwh.GotoAndStop(stripe,"back_",2);
		}
	}
