	_g.set(iriysoft_text_LocId.kTutorial1Txt1,"Thưa Chúa! Thành trì lân cận bị undead chiếm! Phải bảo vệ lâu đài!\n\nChọn lâu đài.");
	_g.set(iriysoft_text_LocId.kTutorial1Txt2,"Vệ binh tinh nhuệ sẵn sàng bảo vệ đất ta.\n\nBấm nút Vệ binh để thuê đội đầu tiên.");
	_g.set(iriysoft_text_LocId.kTutorial1Txt3,"Undead đang tiến tới, thưa Chúa!\n\nKéo icon Vệ binh lên đội địch để tấn công!");
	_g.set(iriysoft_text_LocId.kTutorial1Txt4,"Tuyệt! Trật tự đã trở lại. Đất tạo vàng — dùng để thuê Vệ binh và Cung thủ.\n\nLâu đài chỉ nuôi được 2 đội. Chiếm thị trấn này để thuê thêm.");
	_g.set(iriysoft_text_LocId.kTutorial1Txt5,"Trận chiến vẻ vang! Hãy để quân ở thị trấn một lúc để sửa thành và tăng cường.\n\nSau đó đuổi Undead khỏi lâu đài phía Bắc.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt1,"Thưa Chúa, man tộc Bầy Đoàn chiếm lâu đài kiên cố phía Bắc. Trại ta còn chưa nuôi nổi một đội. Nông trại cho thêm điểm tiếp tế.\n\nChọn chỗ xây và bấm nút nông trại.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt1_1,"Giờ bấm nút Nông trại để xây.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt2,"Tốt lắm! Giờ thuê đội và tấn công.\n\nGặp Ogre trên đường — hạ chúng và lấy rương báu.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt3,"Nên gom từ 2 đội trở lên.\n\nKéo khung chọn qua các icon để chọn nhiều đội.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt4,"Tu sĩ đồng minh sống sót và giúp ta.\n\nCắm Cờ Thánh hóa — lính gần cờ sẽ được hồi máu.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt5,"Tướng khuyên đánh Tháp phép trước. Nên gom từ 2 đội. Kéo khung chọn qua icon để chọn nhiều đội.\nVà đừng quên lấy rương báu!");
	_g.set(iriysoft_text_LocId.kTutorial2Txt6,"Chúc mừng! Tháp phép cho sức mạnh phép và thánh. Có thể thuê lính đặc biệt. Tháp cũng nạp tuyệt kỹ.\n\nBấm ngay để giải phóng sức mạnh Chúa!");
	_g.set(iriysoft_text_LocId.kTutorial2Txt5_1,"Tướng khuyên đánh Tháp phép trước. Nên gom từ 2 đội. Kéo khung chọn qua icon để chọn nhiều đội.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt7,"Ánh sáng chói lòa! Hóa thân Chúa đến trừng phạt kẻ ngoại đạo! Quét sạch man tộc khỏi đất ta.");
	_g.set(iriysoft_text_LocId.kTutorial2Txt8,"Tướng quá thận trọng. Lãnh đạo dũng cảm chiếm được mọi thành!\n\nĐến lúc chiếm tháp phép.");
