	_g.set(iriysoft_text_LocId.kRedFaction,"ОРДА");
	_g.set(iriysoft_text_LocId.kRedDescr,"Багровая Орда - жестокие варвары. Ордынская кавалерия сметает все на своем пути, а шаманы жаждут познать секреты темной магии ");
	_g.set(iriysoft_text_LocId.kRedCompleteToPlay,"ЗАВЕРШИ МИССИИ 1 и 2 КАМПАНИИ ВЕСТАРИИ, ЧТОБЫ ОТКРЫТЬ");
